import numpy as np

def vector_metrics(x, y, eps=1e-12):
    x = np.asarray(x, dtype=float)
    y = np.asarray(y, dtype=float)
    if x.shape != y.shape:
        raise ValueError('same shape required')
    nx, ny = np.linalg.norm(x), np.linalg.norm(y)
    if nx < eps or ny < eps:
        cosine = np.nan
    else:
        cosine = float((x @ y) / (nx * ny))
    return {
        'norm_x': float(nx),
        'dot': float(x @ y),
        'distance': float(np.linalg.norm(x - y)),
        'cosine': cosine,
    }

import numpy as np

def safe_cosine(x, y, eps=1e-12):
    x = np.asarray(x, dtype=float)
    y = np.asarray(y, dtype=float)
    if x.shape != y.shape:
        raise ValueError('same shape required')
    nx, ny = np.linalg.norm(x), np.linalg.norm(y)
    if nx < eps or ny < eps:
        raise ValueError('cosine is undefined for a zero vector')
    return float((x @ y) / (nx * ny))

import numpy as np

def weighted_distance(x, y, w):
    x, y, w = map(lambda a: np.asarray(a, dtype=float), (x, y, w))
    if x.shape != y.shape or x.shape != w.shape:
        raise ValueError('x, y, w must have the same shape')
    if np.any(w < 0):
        raise ValueError('weights must be non-negative')
    return float(np.sqrt(np.sum(w * (x - y) ** 2)))
